{"path": "zipper.py", "content": """"A zipper for binary trees.

Trees are dicts of the form {"value": v, "left": tree_or_None, "right": tree_or_None}.
Zippers are immutable: every navigation or modification returns a new Zipper.
"""


def _copy(tree):
    if tree is None:
        return None
    return {
        "value": tree["value"],
        "left": _copy(tree["left"]),
        "right": _copy(tree["right"]),
    }


class Zipper:
    def __init__(self, focus, path=()):
        # focus: subtree dict at the focus.
        # path: tuple of breadcrumbs (direction, parent_value, other_subtree),
        # innermost last. direction is "left" if focus is the parent's left child.
        self._focus = focus
        self._path = path

    @staticmethod
    def from_tree(tree):
        if tree is None:
            return None
        return Zipper(_copy(tree))

    def value(self):
        return self._focus["value"]

    def _replace(self, **changes):
        node = dict(self._focus)
        node.update(changes)
        return Zipper(node, self._path)

    def set_value(self, value):
        return self._replace(value=value)

    def left(self):
        child = self._focus["left"]
        if child is None:
            return None
        crumb = ("left", self._focus["value"], self._focus["right"])
        return Zipper(child, self._path + (crumb,))

    def set_left(self, tree):
        return self._replace(left=_copy(tree))

    def right(self):
        child = self._focus["right"]
        if child is None:
            return None
        crumb = ("right", self._focus["value"], self._focus["left"])
        return Zipper(child, self._path + (crumb,))

    def set_right(self, tree):
        return self._replace(right=_copy(tree))

    def up(self):
        if not self._path:
            return None
        direction, value, other = self._path[-1]
        if direction == "left":
            parent = {"value": value, "left": self._focus, "right": other}
        else:
            parent = {"value": value, "left": other, "right": self._focus}
        return Zipper(parent, self._path[:-1])

    def to_tree(self):
        zipper = self
        while True:
            parent = zipper.up()
            if parent is None:
                return _copy(zipper._focus)
            zipper = parent

    def __eq__(self, other):
        if not isinstance(other, Zipper):
            return NotImplemented
        return self._focus == other._focus and self._path == other._path

    def __repr__(self):
        return f"Zipper({self._focus!r}, {self._path!r})"
